const fs = require('fs');
const child_process = require('child_process');

const currentLock = JSON.parse(fs.readFileSync('package-lock.json', 'utf8'));
const headLockStr = child_process.execSync('git show HEAD:package-lock.json', { encoding: 'utf8' });
const headLock = JSON.parse(headLockStr);

function getVersions(lock) {
  const versions = {};
  if (lock.packages) {
    for (const [name, pkg] of Object.entries(lock.packages)) {
      if (name === '') continue;
      const cleanName = name.replace(/^node_modules\//, '');
      if (pkg.version) {
        versions[cleanName] = pkg.version;
      }
    }
  }
  if (lock.dependencies) {
    for (const [name, pkg] of Object.entries(lock.dependencies)) {
      if (pkg.version) {
        versions[name] = pkg.version;
      }
    }
  }
  return versions;
}

const currentVersions = getVersions(currentLock);
const headVersions = getVersions(headLock);

const diff = {};
for (const [name, ver] of Object.entries(currentVersions)) {
  if (headVersions[name] !== ver) {
    diff[name] = { head: headVersions[name], current: ver };
  }
}
for (const [name, ver] of Object.entries(headVersions)) {
  if (!currentVersions[name]) {
    diff[name] = { head: ver, current: undefined };
  }
}
console.log(JSON.stringify(diff, null, 2));
